def retry_with_retries(func: callable) -> Callable[..., Any]:
    """
    带重试的装饰器：自动重试最多 retries 次。

    :param func: 原始函数，不接受任何参数。
    :param retries: 最多重试次数（默认 3）。
    :return: 返回一个新的包装函数，原函数结构不变。
    """

    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            # 执行最多 retries 次重试
            max_retries = retries
            while True:
                try:
                    result = func(*args, **kwargs)
                    if result is not None:
                        break
                except Exception as inner_e:
                    pass

                # 尝试再调用一次（循环）
                if max_retries > 0:
                    retries -= 1
                    if retries <= 0:
                        raise  # 达到上限，抛出新异常


# 使用示例

